    if (
        annotation_is_pydantic_v1(type_)
        or isinstance(field_info, may_v1.FieldInfo)
        or version == "1"
    ):
        from fastapi._compat import v1

        try:
            return v1.ModelField(**v1_kwargs)  # type: ignore[return-value]
        except RuntimeError:
            raise fastapi.exceptions.FastAPIError(
                _invalid_args_message.format(type_=type_)
            ) from None
    else:
        field_info = field_info or FieldInfo(
            annotation=type_, default=default, alias=alias
        )
        kwargs = {"mode": mode, "name": name, "field_info": field_info}
        try:
            return v2.ModelField(**kwargs)  # type: ignore[return-value,arg-type]
        except PydanticSchemaGenerationError:
            raise fastapi.exceptions.FastAPIError(
                _invalid_args_message.format(type_=type_)
            ) from None
    # Pydantic v2 is not installed, but it's not a Pydantic v1 ModelField, it could be
    # a Pydantic v1 type, like a constrained int
    from fastapi._compat import v1

    try:
        return v1.ModelField(**v1_kwargs)
    except RuntimeError:
        raise fastapi.exceptions.FastAPIError(
            _invalid_args_message.format(type_=type_)
        ) from None
```

If we remove Pydantic v1 support, we should remove the conditional logic that branches to `v1.ModelField` and the dependency on `annotation_is_pydantic_v1`.

The logic seems to be: if it's v1 compatible, use `v1.ModelField`, otherwise use `v2.ModelField`.

Since we are dropping v1 support, we should probably enforce v2 usage and remove the v1 path entirely.

The dependency on `annotation_is_pydantic_v1` is also in `fastapi/dependencies/utils.py`.

